/* Forward declarations for native settings callbacks.
 *
 * These two name ONE window out of however many are open. Everything that
 * reads them must go through liu_rebind_globals() when that window dies —
 * see the window table below main()'s helpers. */
static AppState *g_app_ptr = NULL;
static PlatformWindow *g_window_ptr = NULL;

/* Multi-window helpers, defined with the window table further down but needed
 * by app-layer helpers that sit above it. */
static void liu_broadcast_config(const AppState *src, bool reload_font);
static void liu_agentctl_apply_config(const AppConfig *c);
