static bool app_scroll_file_viewer(FileBrowser *fb, f32 dx, f32 dy, u32 mods,
                                   bool precise, f32 dpi, f32 mx, f32 my) {
    if (!fb || fb->view_mode == FVIEW_NONE) return false;

    f32 line_h = 16.0f * (dpi > 0.0f ? dpi : 1.0f);
    /* Shift+wheel = horizontal, the platform convention. AppKit only maps it
     * for NSScrollView, so raw NSEvents still arrive as dy — swap manually. */
    if ((mods & MOD_SHIFT) && dx == 0.0f) { dx = dy; dy = 0.0f; }
    f32 dy_px = precise ? dy : dy * line_h;

    /* Graph view: scroll = zoom anchored at the CURSOR (the world point under
     * the pointer stays put), matching every map/canvas tool. The zoom math,
     * device-split sensitivity and clamps live in fb_graph_scroll — one
     * implementation, no forked constants. (mx,my) are framebuffer coords;
     * the graph handler wants them relative to the canvas rect it cached at
     * render time. Setting graph_user_zoomed there also stops the entrance
     * auto-fit camera glide from undoing the zoom. */
    if (fb->view_mode == FVIEW_GRAPH) {
        fb_graph_scroll(fb, dy, precise,
                        mx - fb->graph_view_x, my - fb->graph_view_y,
                        fb->graph_view_w, fb->graph_view_h);
        return true;
    }

    bool md_render_mode =
        (fb->view_mode == FVIEW_MARKDOWN &&
         fb->md_doc &&
         !fb->md_raw_mode);

    if (md_render_mode) {
        if (dx != 0.0f) {
            f32 delta = precise ? dx : dx * line_h * PLATFORM_VIEW_WHEEL_LINES;
            fb->md_table_scroll_x = fmaxf(0.0f, fminf(fb->md_table_scroll_x - delta, fb->md_table_overflow));
        }
        fb->view_scroll_px -= dy_px;
        if (fb->view_scroll_px < 0.0f)
            fb->view_scroll_px = 0.0f;

        /* The last useful scroll position puts the END of the document at the
         * BOTTOM of the viewport. Clamping to (content - 4 lines) instead
         * would let the reader scroll the whole document off the top and sit
         * facing a screenful of empty space — the taller the document, the
         * more of it there would be to scroll through. */
        f32 view_h = fb->md_view_h > 0.0f ? fb->md_view_h : line_h * 10.0f;
        f32 max_y = fb->view_content_px - view_h;
        if (max_y < 0.0f) max_y = 0.0f;
        if (fb->view_scroll_px > max_y)
            fb->view_scroll_px = max_y;
    } else {
        /* The view converts wheel input to source lines for code/text, or
         * pixel rows for the wrapped Markdown editor. */
        fb_scroll_lines(fb, dy, precise, line_h);

        /* Horizontal — code/plain text and unwrapped Markdown fences.
         * Trackpad pixels accumulate
         * into whole columns so a gentle swipe doesn't warp; a wheel notch
         * moves 3 columns. Clamped against the longest visible line the last
         * render measured, so you can't scroll into empty space forever. */
        if (dx != 0.0f &&
            (fb->view_mode == FVIEW_TEXT || fb->view_mode == FVIEW_CODE || fb_md_edit_active(fb))) {
            f32 cw = fb->code_cw > 0.0f ? fb->code_cw
                                        : 8.0f * (dpi > 0.0f ? dpi : 1.0f);
            fb->hscroll_accum_px += precise ? dx : dx * cw * PLATFORM_VIEW_WHEEL_LINES;
            i32 hstep = (i32)(fb->hscroll_accum_px / cw);
            if (hstep != 0) {
                fb->hscroll_accum_px -= (f32)hstep * cw;
                fb->view_scroll_x -= hstep;
                i32 vis = fb->code_visible_cols > 0 ? fb->code_visible_cols : 80;
                i32 max_x = fb->code_max_vis_cols - vis / 2;
                if (fb->view_scroll_x > max_x) fb->view_scroll_x = max_x;
                if (fb->view_scroll_x < 0) fb->view_scroll_x = 0;
            }
        }
    }

    return true;
}

/* A key that scrolls a rendered note (the reader has no caret): by the same scroller the
 * wheel uses, so the clamps are the wheel's. TRUE when the key was one of them. */
static bool app_md_read_key(AppState *app, FileBrowser *fb, u32 key, u32 mods) {
    f32 dpi = app->dpi_scale > 0.0f ? app->dpi_scale : 1.0f;
    f32 line_h = 16.0f * dpi;
    f32 view_h = fb->md_view_h > 0.0f ? fb->md_view_h : line_h * 10.0f;
    f32 page = view_h - 2.0f * line_h;
    if (page < line_h) page = line_h;
    bool cmd = (mods & MOD_APP) != 0, shift = (mods & MOD_SHIFT) != 0;
    f32 dy = 0.0f;
    switch (key) {
    case KEY_UP:        if (cmd) dy = 1.0e7f; else if (!shift) dy = 3.0f * line_h; else return false; break;
    case KEY_DOWN:      if (cmd) dy = -1.0e7f; else if (!shift) dy = -3.0f * line_h; else return false; break;
    case KEY_SPACE:     if (cmd) return false; dy = shift ? page : -page; break;
    case KEY_PAGE_UP:   dy = page;  break;
    case KEY_PAGE_DOWN: dy = -page; break;
    case KEY_HOME:      dy = 1.0e7f;  break;
    case KEY_END:       dy = -1.0e7f; break;
    default: return false;
    }
    return app_scroll_file_viewer(fb, 0.0f, dy, 0, true, dpi, 0.0f, 0.0f);
}

/* Route a clicked markdown link/tag by its MdLinkRect kind. Wikilinks/embeds
 * and relative .md links open in-app (resolved against the doc's folder);
 * everything else (http, mailto, images, non-md files) goes to the OS. Tag
 * clicks are handled in a later phase (tag index/filter). */
static void app_open_md_link_anchored(FileBrowser *fb, const char *url, u8 kind,
                                      const char *anchor, bool anchor_is_block) {
    if (!fb) return;
    /* "[[#Heading]]" — no note part, so the target is a section of the note
     * already open. Scroll, don't open. */
    if ((!url || !url[0]) && anchor && anchor[0] && kind == MD_LINKRECT_WIKILINK) {
        fb_md_seek_anchor(fb, anchor, anchor_is_block);
        return;
    }
    if (!url || !url[0]) return;
    if (kind == MD_LINKRECT_TAG) {
        /* Open the knowledge graph for this folder — tags are pseudo-nodes,
         * so the clicked tag and the notes carrying it become visible. */
        if (!fb_graph_active(fb)) fb_toggle_graph(fb);
        return;
    }

    const char *base = (fb->md_doc) ? fb->md_doc->base_dir : NULL;
    char resolved[FB_MAX_PATH * 2];
    usize ul = strlen(url);
    bool ends_md = (ul > 3 && strcasecmp(url + ul - 3, ".md") == 0) ||
                   (ul > 9 && strcasecmp(url + ul - 9, ".markdown") == 0);

    if (kind == MD_LINKRECT_WIKILINK || kind == MD_LINKRECT_EMBED) {
        /* Resolve a note name → .md relative to the current doc's folder
         * (same-folder is the common case; cross-folder needs a vault index). */
        if (url[0] == '/')
            snprintf(resolved, sizeof resolved, "%s%s", url, ends_md ? "" : ".md");
        else if (base)
            snprintf(resolved, sizeof resolved, "%s/%s%s", base, url, ends_md ? "" : ".md");
        else
            snprintf(resolved, sizeof resolved, "%s%s", url, ends_md ? "" : ".md");
        if (fb_open_md_path(fb, resolved) && anchor && anchor[0]) {
            /* "[[Note#Installation]]" means BOTH open and go there. Armed after
             * the open so it resolves against the document just loaded. */
            fb_md_seek_anchor(fb, anchor, anchor_is_block);
        }
        return;
    }

    /* URL / IMAGE. What kind of destination it is comes from one rule
     * (ui/markdown/md_link_target.h): any `scheme:` is somebody else's to open,
     * `#anchor` is a place in THIS document, and a path may carry a `#fragment`
     * of its own. A plain "does it contain ://" test would join `mailto:` onto
     * the folder as a file name, turn `[Install](#install)` into the path
     * `<dir>/#install`, and not see `docs/api.md#use` as a Markdown file at all.
     */
    MdLinkTarget lt = md_link_classify(url, ul);
    if (lt.kind == MD_LINK_NONE) return;
    if (lt.kind == MD_LINK_EXTERNAL) { platform_open_url(url); return; }
    char frag[MD_LINK_SLUG_MAX];
    md_link_percent_decode(lt.fragment, lt.fragment_len, frag, sizeof frag);
    if (lt.kind == MD_LINK_FRAGMENT) {
        /* The anchor GitHub would give the heading (`#whats-new-in-c`), or
         * the heading's own text. */
        u32 hb = fb->md_doc ? md_link_find_heading(fb->md_doc, lt.fragment, lt.fragment_len)
                            : MD_LINK_NO_HEADING;
        if (hb != MD_LINK_NO_HEADING) {
            fb->md_seek_block = hb;
            fb->md_seek_y = 0.0f;
        } else if (frag[0]) {
            fb_md_seek_anchor(fb, frag, false);
        }
        return;
    }
    char path[FB_MAX_PATH];
    md_link_percent_decode(lt.path, lt.path_len, path, sizeof path);
    if (!path[0]) return;
    usize pl = strlen(path);
    bool path_md = (pl > 3 && strcasecmp(path + pl - 3, ".md") == 0) ||
                   (pl > 9 && strcasecmp(path + pl - 9, ".markdown") == 0);
    const char *target = path;
    if (path[0] != '/' && base) {
        snprintf(resolved, sizeof resolved, "%s/%s", base, path);
        target = resolved;
    }
    /* A relative/absolute .md link opens in the in-app viewer, at its section. */
    if (kind == MD_LINKRECT_URL && path_md) {
        if (fb_open_md_path(fb, target)) {
            if (frag[0]) fb_md_seek_anchor(fb, frag, false);
            return;
        }
        /* Refused because the note that is open has unsaved edits: it says
         * so, and the link is not handed to another app instead. */
        if (fb_editor_dirty(fb)) return;
    }
    platform_open_url(target);
}

/* If a code-block Copy button sits under (mx,my), copy that block's text to the
 * clipboard and report the click as consumed. */
static bool app_md_try_copy(AppState *app, FileBrowser *fb, f32 mx, f32 my) {
    const u8 *txt = NULL; u32 len = 0;
    if (!fb_md_hit_copy(fb, mx, my, &txt, &len) || !txt) return false;
    usize allocation_size;
    char *buf = checked_add_usize((usize)len, 1u, &allocation_size)
        ? (char *)malloc(allocation_size) : NULL;
    bool copied = false;
    if (buf) {
        memcpy(buf, txt, len);
        buf[len] = '\0';
        copied = app_clipboard_copy(app, buf, NULL);   /* toasts a refusal */
        free(buf);
    } else {
        app_show_toast(app, "Copy failed: out of memory");
    }
    /* "Copied" on the button itself — ONLY when the clipboard holds the block.
     * It is stamped after the write succeeds, so the button never claims a
     * copy the paste would not deliver. `txt` is the block's raw pointer,
     * which is exactly what the renderer compares against, so no block id is
     * needed. */
    if (copied) {
        fb->md_copy_flash_src = txt;
        fb->md_copy_flash_at  = platform_time_sec();
    }
    return true;   /* consumed the click either way */
}

/* Identifies which UI surface currently owns scroll input. Used to discard
 * stale momentum-phase scroll events whose gesture began over a different
 * surface: a trackpad fling on the terminal keeps emitting inertial scroll
 * events for ~1 s after the fingers lift, and if a modal (e.g. the Cmd+K
 * palette) opens during that tail, those events would scroll the freshly
 * opened modal on their own. Any non-zero id is a modal/overlay; 0 is the
 * base terminal / file-browser surface. */
static i32 app_scroll_context_id(const AppState *app) {
    if (app->palette_active)             return 1;
    if (app->transcript_viewer_active)   return 2;
    if (app->settings.open)              return 3;
    if (app->sites.active)               return 4;
    if (app->ssh_dialog_active)          return 5;
    if (app->create_theme_active)        return 6;
    if (app->search_active)              return 7;
    if (app->broadcast_overlay_active)   return 8;
    if (app->port_forward_dialog_active) return 9;
    if (app->kbi_dialog_active)          return 10;
    if (app->key_manager_active)         return 11;
    if (app->known_hosts_open)           return 12;
    if (app->hostkey_dialog_active)      return 13;
    if (app->passphrase_dialog_active)   return 14;
    if (app->agent_picker_active)        return 15;
    if (app->cmd_history_active)         return 16;
    return 0;
}

/* The group a tab is in on the strip, or -1: a group index that names a slot
 * no longer in use counts as none (the painter and the hit test agree). */
static i32 app_tab_live_group(const AppState *app, i32 ti) {
    if (!app || ti < 0 || ti >= app->tab_count) return -1;
    i32 g = app->tabs[ti].group_index;
    return (g >= 0 && g < MAX_TAB_GROUPS && app->tab_groups[g].used) ? g : -1;
}

/* The tab strip's slots and groups where render_toolbar lays them out
 * (ui/tab_drop.h does the arithmetic; this hands it the window's numbers). */
_Static_assert(MAX_TABS <= TAB_STRIP_MAX_TABS && MAX_TAB_GROUPS <= TAB_STRIP_MAX_GROUPS,
               "TabStripLayout must hold every tab and group");
static void liu_tab_strip_layout(const AppState *app, TabStripLayout *L) {
    i32 grp[MAX_TABS];
    f32 w[MAX_TABS];
    u8  used[MAX_TAB_GROUPS], collapsed[MAX_TAB_GROUPS];
    f32 chip[MAX_TAB_GROUPS];
    i32 n = app->tab_count < MAX_TABS ? app->tab_count : MAX_TABS;
    for (i32 i = 0; i < n; i++) {
        grp[i] = app_tab_live_group(app, i);
        w[i]   = app->_tab_w + app->_tab_extra_w[i];
    }
    for (i32 g = 0; g < MAX_TAB_GROUPS; g++) {
        used[g]      = app->tab_groups[g].used ? 1 : 0;
        collapsed[g] = app->tab_groups[g].collapsed ? 1 : 0;
        chip[g]      = used[g] ? app_get_group_chip_width(app, g) : 0.0f;
    }
    tab_strip_layout(L, app->_tab_bar_x - app->_tab_scroll_x, app->_tab_gap,
                     grp, w, n, used, collapsed, chip, MAX_TAB_GROUPS);
}

/* Tear down tab-drag state after a drop, a cancel, or an abandoned drag.
 *
 * A drag that reaches the terminal area switches the view to the split
 * destination so the overlay previews the real target (see the EVENT_MOUSE_MOVE
 * handler). Any exit that is *not* a completed split therefore has to put the
 * dragged tab back on screen — otherwise cancelling a drag silently swaps
 * which tab the user is looking at. */
static void app_tab_drag_reset(AppState *app, bool restore_view) {
    if (!app) return;
    /* Process-wide, not per window: only one drag runs at a time (one button
     * is down), and the caret it leaves lives on a DIFFERENT window's state. */
    liu_tab_xdrop_clear();
    if (restore_view && app->tab_drag_into_split &&
        app->tab_drag_index >= 0 && app->tab_drag_index < app->tab_count &&
        app->active_tab != app->tab_drag_index) {
        app_switch_tab(app, app->tab_drag_index);
    }
    app->tab_dragging          = false;
    app->tab_drag_pending      = false;
    app->tab_drag_index        = -1;
    app->tab_drag_target       = -1;
    app->tab_drag_target_group = -1;
    app->tab_drag_home_group   = -1;
    app->tab_drag_offset_x     = 0;
    app->tab_drag_into_split   = false;
    app->tab_drag_split_zone   = 0;
    app->tab_drag_split_dst    = -1;
    app->tab_drag_prev_active  = -1;
}

static i32 app_open_markdown_viewer_tab(AppState *app, const char *path) {
    if (!app || !path || !path[0]) return -1;

    const char *slash = strrchr(path, '/');
    char dir[FB_MAX_PATH];
    char base[512];
    if (slash) {
        i32 dlen = (i32)(slash - path);
        if (dlen <= 0) {
            snprintf(dir, sizeof(dir), "/");
        } else {
            if ((usize)dlen >= sizeof(dir)) return -1;
            snprintf(dir, sizeof(dir), "%.*s", dlen, path);
        }
        snprintf(base, sizeof(base), "%s", slash + 1);
    } else {
        snprintf(dir, sizeof(dir), ".");
        snprintf(base, sizeof(base), "%s", path);
    }
    if (!base[0]) return -1;

    i32 tab_idx = app_new_filebrowser_tab(app, dir);
    if (tab_idx < 0 || tab_idx >= app->tab_count) return -1;

    Tab *tab = &app->tabs[tab_idx];
    if (!tab->fb) return tab_idx;
    if (!fb_open_path(tab->fb, path, false)) {
        app_close_tab(app, tab_idx);
        return -1;
    }
    tab->fb_viewer_only = true;
    if (tab->fb->view_mode == FVIEW_MARKDOWN)
        tab->fb->md_raw_mode = false;
    snprintf(tab->title, sizeof(tab->title), "%s", base);
    return tab_idx;
}

/* Open `path` in the Markdown EDITOR rather than the reader. Create Note lands
 * here: the file is a bare H1 waiting for the user to write it, so dropping
 * them on the rendered view would only cost them a Cmd+E. */
static bool app_open_note_editor_tab(AppState *app, const char *path) {
    i32 ti = app_open_markdown_viewer_tab(app, path);
    if (ti < 0 || ti >= app->tab_count) return false;
    FileBrowser *fb = app->tabs[ti].fb;
    if (!fb) return false;
    if (!fb->md_raw_mode) fb_md_toggle_edit(fb);   /* read → edit */
    return true;
}

/* Open `path` as a full IDE tab: the file-explorer rail on the left, the
 * code/text editor filling the rest of the window.
 *
 * `path` may be a directory (a project root — the tab opens on the folder with
 * no document yet) or a file (its folder becomes the rail and the file opens in
 * the editor). This is the same FileBrowser tab the file browser already used;
 * what makes it read as an IDE is that document views dock the list as a narrow
 * rail (fb_view_wants_rail) instead of splitting the tab in half.
 *
 * Returns the new tab index, or -1 if nothing could be opened. */
static i32 app_open_code_editor_tab(AppState *app, const char *path) {
    if (!app || !path || !path[0]) return -1;

    char dir[FB_MAX_PATH];
    char base[512];
    base[0] = '\0';

    struct stat st;
    bool is_dir = (stat(path, &st) == 0 && S_ISDIR(st.st_mode));
    if (is_dir) {
        snprintf(dir, sizeof(dir), "%s", path);
    } else {
        const char *slash = strrchr(path, '/');
        if (slash) {
            i32 dlen = (i32)(slash - path);
            if (dlen <= 0) snprintf(dir, sizeof(dir), "/");
            else {
                if ((usize)dlen >= sizeof(dir)) return -1;
                snprintf(dir, sizeof(dir), "%.*s", dlen, path);
            }
            snprintf(base, sizeof(base), "%s", slash + 1);
        } else {
            snprintf(dir, sizeof(dir), ".");
            snprintf(base, sizeof(base), "%s", path);
        }
        if (!base[0]) return -1;
    }

    i32 tab_idx = app_new_filebrowser_tab(app, dir);
    if (tab_idx < 0 || tab_idx >= app->tab_count) return -1;

    Tab *tab = &app->tabs[tab_idx];
    if (base[0] && tab->fb && !fb_open_path(tab->fb, path, true)) {
        app_close_tab(app, tab_idx);
        return -1;
    }
    app_refresh_fb_tab_title(tab);
    return tab_idx;
}

